const raw = $json;

const content =
  raw.output_text ||
  raw.message?.content ||
  raw.choices?.[0]?.message?.content ||
  raw.text ||
  "";

try {
  const parsed = JSON.parse(content);
  return [{ ok: true, result: parsed }];
} catch (e) {}

const stripped = content.replace(/```json|```/gi, "").trim();
try {
  const parsed = JSON.parse(stripped);
  return [{ ok: true, result: parsed }];
} catch (e) {}

const match = stripped.match(/\{[\s\S]*\}$/);
if (match) {
  try {
    const parsed = JSON.parse(match[0]);
    return [{ ok: true, result: parsed }];
  } catch (e) {}
}

return [{
  ok: false,
  result: {
    error: "Model output was not valid JSON",
    raw: content
  }
}];

const b = $json;

// Defaults / normalization
const planDays = Number(b.planDays || 7);
const people = Number(b.people || 1);
const mealsPerDay = Array.isArray(b.mealsPerDay) ? b.mealsPerDay : (b.mealsPerDay ? [b.mealsPerDay] : ["breakfast","lunch","dinner"]);
const cuisine = Array.isArray(b.cuisine) ? b.cuisine : (b.cuisine ? [b.cuisine] : []);
const allergies = Array.isArray(b.allergies) ? b.allergies : (b.allergies ? [b.allergies] : []);
const avoidIngredients = Array.isArray(b.avoidIngredients) ? b.avoidIngredients : (b.avoidIngredients ? [b.avoidIngredients] : []);

const goal = b.goal || "balanced";
const dietStyle = b.dietStyle || "";
const budgetLevel = b.budgetLevel || "medium";
const timePerMeal = Number(b.timePerMeal || 30);
const calorieTarget = b.calorieTarget ? String(b.calorieTarget) : "";
const notes = b.notes || "";

const system = `You are a meal planning assistant. Output ONLY valid JSON. No markdown.`;

const schema = {
  planMeta: {
    days: planDays,
    people,
    goal,
    dietStyle,
    mealsPerDay,
    cuisine,
    allergies,
    avoidIngredients,
    budgetLevel,
    timePerMealMinutes: timePerMeal,
    calorieTarget,
    notes
  },
  groceryList: [
    { item: "string", quantity: "string", category: "Produce|Meat|Seafood|Dairy|Pantry|Frozen|Spices|Other" }
  ],
  days: [
    {
      day: 1,
      meals: [
        {
          mealType: "breakfast|lunch|dinner|snack",
          title: "string",
          cuisine: "string",
          prepTimeMinutes: 10,
          cookTimeMinutes: 15,
          servings: people,
          ingredients: [{ name: "string", amount: "string" }],
          steps: ["string"],
          nutrition: {
            calories: 0,
            protein_g: 0,
            carbs_g: 0,
            fat_g: 0,
            fiber_g: 0,
            sugar_g: 0
          },
          diabeticNotes: "string"
        }
      ]
    }
  ]
};

const userPrompt = `Create a ${planDays}-day meal plan for ${people} people.

Constraints:
- Goal: ${goal}
- Diet style: ${dietStyle || "none specified"}
- Meals per day: ${mealsPerDay.join(", ")}
- Cuisine preferences: ${cuisine.length ? cuisine.join(", ") : "no preference"}
- Allergies: ${allergies.length ? allergies.join(", ") : "none"}
- Avoid ingredients: ${avoidIngredients.length ? avoidIngredients.join(", ") : "none"}
- Budget level: ${budgetLevel}
- Time per meal: <= ${timePerMeal} minutes
- Calorie target (optional): ${calorieTarget || "none"}
- Notes: ${notes || "none"}

Output requirements:
- Return ONLY JSON.
- Match this JSON structure exactly (fill with real values): ${JSON.stringify(schema)}
- Make meals practical and repeat ingredients to reduce grocery cost.
- Ensure diabetic-friendly choices when goal mentions diabetes.
`;

return [{
  system,
  userPrompt,
  planDays,
  people
}];
